package dev.tomerklein.dradis.commands

import android.content.Context
import android.graphics.BitmapFactory
import java.io.File
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow

/**
 * Saves pictures received on custom topics to app-private storage and exposes
 * them to the gallery screen. File names are generated by [GalleryDir] and never
 * taken from a payload; the newest [GalleryDir.MAX_FILES] are kept.
 */
class PictureStore(context: Context) {

    private val files = GalleryDir(File(context.applicationContext.filesDir, "gallery"))

    private val _changes = MutableStateFlow(0)
    /** Bumped after every save or delete so the UI can re-list. */
    val changes: StateFlow<Int> = _changes

    /** Returns false if the bytes are not a decodable, reasonably sized image. */
    fun save(image: ImagePayload.Image): Boolean = runCatching {
        val bounds = BitmapFactory.Options().apply { inJustDecodeBounds = true }
        BitmapFactory.decodeByteArray(image.bytes, 0, image.bytes.size, bounds)
        val w = bounds.outWidth
        val h = bounds.outHeight
        if (w <= 0 || h <= 0 || w > MAX_SIDE || h > MAX_SIDE || w.toLong() * h > MAX_PIXELS) return false
        files.add(image.bytes, image.extension)
        _changes.value++
        true
    }.getOrDefault(false)

    fun list(): List<GalleryItem> = files.list()

    fun fileFor(name: String): File? = files.fileFor(name)

    fun delete(name: String): Boolean = files.delete(name).also { if (it) _changes.value++ }

    private companion object {
        const val MAX_SIDE = 8000
        const val MAX_PIXELS = 40_000_000L
    }
}
